// A tenant admin can edit amfaConfigs.asmurl / asm_portal_url, so a stored
// ASM URL is fetched only when its origin is one of the platform's ASM
// origins. ASM_SERVICE_URL and ASM_PORTAL_URL are set on every service Lambda
// by createSharedLambda (packages/service/cdk/lib/shared-api-gateway.ts).
// Same file in every service Lambda dir that fetches a stored ASM URL.
export const platformAsmOrigins = () =>
  [process.env.ASM_SERVICE_URL, process.env.ASM_PORTAL_URL]
    .filter(Boolean)
    .map((u) => new URL(u).origin);

export const isPlatformAsmUrl = (url) => {
  try {
    return platformAsmOrigins().includes(new URL(url).origin);
  } catch {
    return false;
  }
};
